using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<WeatherForecast> typeInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> => Type={typeInfo.Type.Name}, Kind={typeInfo.Kind}");

var forecast = new WeatherForecast("Seattle", 62);
string json = JsonSerializer.Serialize(forecast, typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type that IS resolvable (default reflection resolver handles it)
if (options.TryGetTypeInfo<WeatherForecast>(out var resolved))
    Console.WriteLine($"TryGet WeatherForecast => resolved ({resolved!.Type.Name})");
else
    Console.WriteLine("TryGet WeatherForecast => NOT resolved");

// 2b. Use a source-gen context that only knows about WeatherForecast,
//     so asking for an unknown type returns false instead of throwing.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<int>(out var intInfo))
    Console.WriteLine($"TryGet int => resolved ({intInfo!.Type.Name})");
else
    Console.WriteLine("TryGet int => NOT resolved (metadata unavailable)");

// --- types ---
public record WeatherForecast(string City, int TempF);

[JsonSerializable(typeof(WeatherForecast))]
internal partial class LimitedContext : JsonSerializerContext;

